/* ───── BUBBLES ───── */
const symbols=['®','©','™'];
function spawnBubbles(field,base){
  function make(){
    if(!field.isConnected)return;
    const el=document.createElement('div');el.className='bubble';
    const dur=3.2+Math.random()*4.5,del=Math.random()*0.25;
    el.style.left=(5+Math.random()*90)+'%';
    el.style.fontSize=(10+Math.random()*20)+'px';
    el.style.animationDuration=dur+'s';el.style.animationDelay=del+'s';
    el.style.setProperty('--drift',(-20+Math.random()*40)+'px');
    el.style.setProperty('--spin',(-30+Math.random()*60)+'deg');
    el.style.color=base.replace('{o}',(0.08+Math.random()*0.14).toFixed(2));
    const s=document.createElement('span');s.textContent=symbols[Math.floor(Math.random()*symbols.length)];
    s.style.animationDuration=(1.3+Math.random()*1.4)+'s';el.appendChild(s);
    field.appendChild(el);setTimeout(()=>el.remove(),(dur+del)*1000);
  }
  for(let i=0;i<48;i++)setTimeout(make,i*90);
  setInterval(make,130);
}
document.querySelectorAll('[data-bubbles]').forEach(f=>{
  const map={brown:'rgba(90,58,0,{o})',faint:'rgba(27,27,28,{o})',light:'rgba(255,255,255,{o})'};
  spawnBubbles(f,map[f.dataset.bubbles]||map.brown);
});

