/* ───── DECK ───── */
const slides=Array.from(document.querySelectorAll(".slide")).filter(s=>getComputedStyle(s).display!=="none");
const navWrap=document.getElementById('nav');
let current=0,locked=false;
slides.forEach((s,i)=>{
  const b=document.createElement('button');
  b.className=(i===0?'active':'');
  b.innerHTML='<span class="num">0'+(i+1)+'</span><span class="line"></span>';
  b.setAttribute('aria-label',s.dataset.name||('Section '+(i+1)));
  b.addEventListener('click',()=>goTo(i));
  navWrap.appendChild(b);
});
const navBtns=Array.from(navWrap.children);
function syncNav(){
  const dark=slides[current].dataset.ctx==='dark';
  navWrap.classList.toggle('ctx-dark',dark);
  navWrap.classList.toggle('ctx-light',!dark);
}
function setClasses(){
  slides.forEach((s,i)=>{s.classList.remove('active','above','below');s.classList.add(i===current?'active':(i<current?'above':'below'));});
  navBtns.forEach((b,i)=>b.classList.toggle('active',i===current));
  syncNav();reveal();
}
function reveal(){
  const s=slides[current];
  const h=s.querySelector('.hero');if(h)h.classList.add('go');
  const m=s.querySelector('#manifest');if(m)m.classList.add('go');
}
function goTo(i){if(locked||i===current||i<0||i>slides.length-1)return;locked=true;current=i;setClasses();setTimeout(()=>locked=false,950);}
function next(){goTo(current+1);}function prev(){goTo(current-1);}
document.querySelectorAll('[data-next]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();next();}));

let wheelCD=false;
window.addEventListener('wheel',e=>{e.preventDefault();if(locked||wheelCD||Math.abs(e.deltaY)<12)return;wheelCD=true;setTimeout(()=>wheelCD=false,1000);e.deltaY>0?next():prev();},{passive:false});
window.addEventListener('keydown',e=>{if(['ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();next();}else if(['ArrowUp','PageUp'].includes(e.key)){e.preventDefault();prev();}});
let tY=null;
window.addEventListener('touchstart',e=>tY=e.touches[0].clientY,{passive:true});
window.addEventListener('touchmove',e=>{if(tY===null||locked)return;const dy=tY-e.touches[0].clientY;if(Math.abs(dy)>60){dy>0?next():prev();tY=null;}},{passive:true});

/* ───── ROTOR ───── */
const words=Array.from(document.querySelectorAll('#rotor .word'));
let ri=0;
setInterval(()=>{
  const cur=words[ri],ni=(ri+1)%words.length,nx=words[ni];
  cur.classList.remove('show');cur.classList.add('out');
  nx.classList.remove('out');nx.classList.add('show');
  setTimeout(()=>cur.classList.remove('out'),500);ri=ni;
},2400);

setClasses();